const row = $('Lire l\'édition du jour').first().json;
const ed = JSON.parse(row.contenu);
const destinataires = $input.all().map((i) => i.json).filter((a) => a.email && a.jeton && a.statut === 'actif');
const IMG = 'https://prisme.krady.fr/mail';
const API = 'https://prisme.krady.fr/api';
const F = "font-family:'Helvetica Neue', Helvetica, Arial, sans-serif;";
const RAYONS = [['#38c6e8', '#e3f7fc'], ['#4f7cf5', '#e6edfe'], ['#8a63f0', '#efe9fd'], ['#f06fb0', '#fde9f3'], ['#3fcf9a', '#e3f8f0']];
const IMPACTS = { faible: ['Faible', '●○○'], moyen: ['Moyen', '●●○'], fort: ['Fort', '●●●'] };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const nbsp = (s) => esc(s).replace(/ ([:;?!])/g, '&nbsp;$1').replace(/« /g, '«&nbsp;').replace(/ »/g, '&nbsp;»');

function quand(iso) {
  const d = DateTime.fromISO(String(iso || ''));
  if (!d.isValid) return '';
  const h = Math.floor(DateTime.now().diff(d, 'hours').hours);
  if (h < 1) return 'à l’instant';
  if (h < 24) return 'il y a ' + h + ' h';
  return d.setZone('Europe/Paris').setLocale('fr').toFormat('d LLL yyyy');
}

function sujetDe(ed) {
  const nb = (ed.articles || []).length;
  const jour = DateTime.fromISO(ed.date, { zone: 'Europe/Paris' }).setLocale('fr');
  return 'Prisme · ' + jour.toFormat('d LLL') + ' · ' + (nb === 0 ? 'rien de marquant' : nb + ' nouveauté' + (nb > 1 ? 's' : ''));
}

function rendre(ed, dest, mode) {
  const articles = (ed.articles || []).slice(0, 5);
  const nb = articles.length;
  const jour = DateTime.fromISO(ed.date, { zone: 'Europe/Paris' }).setLocale('fr');
  const dateLongue = jour.toFormat('cccc d LLLL yyyy').replace(/^./, (c) => c.toUpperCase());
  const numero = 'N° ' + Math.max(1, Math.round(jour.startOf('day').diff(DateTime.fromISO('2026-10-08', { zone: 'Europe/Paris' }), 'days').days) + 1);
  const humeur = nb === 0 ? 'dort' : 'lit';
  const humeurAlt = nb === 0 ? 'Tri dort : rien de marquant aujourd’hui' : 'Tri lit les 14 sources';
  const b = ed.bilan || {};
  const lus = b.examines || 0;
  const titre = ed.titre || (nb === 0 ? 'Une journée calme.' : 'L’essentiel de l’IA pour les PM.');
  const preheader = nb === 0 ? 'Rien de marquant aujourd’hui pour un PM.' : (ed.essentiels && ed.essentiels[0]) || titre;
  const inerte = mode === 'apercu';
  const lienVote = (v) => inerte ? '#' : API + '/prisme-vote?d=' + encodeURIComponent(ed.date) + '&v=' + v + '&t=' + encodeURIComponent(dest.jeton);
  const lienDesinscription = mode === 'mail' ? API + '/prisme-desinscription?t=' + encodeURIComponent(dest.jeton) : 'https://prisme.krady.fr';
  const lienNavigateur = inerte ? '#' : API + '/prisme-numero?d=' + encodeURIComponent(ed.date);
  const cible = inerte ? ' target="_blank" rel="noopener"' : ' target="_blank"';

  const essentiel = (txt, i, dernier) => '<tr><td style="padding:' + (i === 0 ? '4px' : '16px') + ' 0 16px 0;' + (dernier ? '' : 'border-bottom:1px solid #dbe3f5;') + '" class="dm-line">'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>'
    + '<td width="56" valign="top" style="width:56px;' + F + 'font-size:30px;line-height:32px;mso-line-height-rule:exactly;font-weight:bold;letter-spacing:-1px;color:#3c4fe0;" class="dm-accent">0' + (i + 1) + '</td>'
    + '<td valign="top" class="dm-soft" style="' + F + 'font-size:15px;line-height:23px;mso-line-height-rule:exactly;color:#33395c;padding-top:4px;">' + nbsp(txt) + '</td>'
    + '</tr></table></td></tr>';

  const article = (a, i) => {
    const r = RAYONS[i % 5];
    const imp = IMPACTS[a.impact] || IMPACTS.moyen;
    const quandTxt = quand(a.date);
    return '<tr><td class="px" style="padding:0 32px 16px 32px;">'
      + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" class="dm-card" style="background:#ffffff;border:1px solid #dbe3f5;border-radius:16px;border-collapse:separate;">'
      + '<tr><td height="5" style="height:5px;line-height:5px;font-size:0;background:' + r[0] + ';border-radius:16px 16px 0 0;">&nbsp;</td></tr>'
      + '<tr><td style="padding:20px 24px 22px 24px;">'
      + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>'
      + '<td style="' + F + 'font-size:11px;line-height:16px;mso-line-height-rule:exactly;font-weight:bold;letter-spacing:1.4px;text-transform:uppercase;color:#4a5172;" class="dm-muted">' + esc(a.type) + '</td>'
      + '<td align="right"><table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td class="dm-pale" style="background:' + r[1] + ';border-radius:999px;padding:5px 11px;' + F + 'font-size:12px;line-height:16px;mso-line-height-rule:exactly;color:#141a3a;white-space:nowrap;"><span class="dm-ink">Impact PM&nbsp;: <b>' + imp[0] + '</b></span>&nbsp;<span style="color:' + r[0] + ';letter-spacing:1px;">' + imp[1] + '</span></td></tr></table></td>'
      + '</tr></table>'
      + '<h3 class="dm-ink" style="margin:14px 0 6px 0;' + F + 'font-size:20px;line-height:26px;mso-line-height-rule:exactly;font-weight:bold;color:#141a3a;">' + esc(a.titre) + '</h3>'
      + '<p class="dm-muted" style="margin:0 0 12px 0;' + F + 'font-size:13px;line-height:18px;mso-line-height-rule:exactly;color:#4a5172;">' + esc(a.source) + (quandTxt ? ' · ' + quandTxt : '') + '</p>'
      + '<p class="dm-soft" style="margin:0 0 18px 0;' + F + 'font-size:15px;line-height:23px;mso-line-height-rule:exactly;color:#33395c;">' + nbsp(a.ce_qui_sort) + ' ' + nbsp(a.pour_un_pm) + '</p>'
      + '<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr><td class="dm-btn" bgcolor="#141a3a" style="background:#141a3a;border-radius:10px;">'
      + '<a href="' + esc(a.url) + '"' + cible + ' style="display:block;padding:11px 20px;' + F + 'font-size:14px;line-height:18px;font-weight:bold;color:#ffffff;text-decoration:none;">Lire&nbsp;&rarr;</a>'
      + '</td></tr></table>'
      + '</td></tr></table></td></tr>';
  };

  const corps = nb === 0
    ? '<tr><td class="px" style="padding:30px 32px 26px 32px;">'
      + '<h2 class="dm-ink" style="margin:0 0 10px 0;' + F + 'font-size:28px;line-height:32px;mso-line-height-rule:exactly;font-weight:bold;letter-spacing:-0.8px;color:#141a3a;">Rien de marquant aujourd’hui.</h2>'
      + '<p class="dm-soft" style="margin:0;' + F + 'font-size:16px;line-height:25px;mso-line-height-rule:exactly;color:#33395c;">Tri a parcouru ' + lus + ' articles venus de 14&nbsp;sources&nbsp;: rien qui change le travail d’un PM aujourd’hui. Rendez-vous demain à 8&nbsp;h&nbsp;30.</p>'
      + '</td></tr>'
    : '<tr><td class="px" style="padding:30px 32px 8px 32px;">'
      + '<p class="dm-muted" style="margin:0 0 6px 0;' + F + 'font-size:11px;line-height:16px;font-weight:bold;letter-spacing:1.4px;text-transform:uppercase;color:#4a5172;">L’essentiel</p>'
      + '<h2 class="dm-ink" style="margin:0 0 14px 0;' + F + 'font-size:28px;line-height:32px;mso-line-height-rule:exactly;font-weight:bold;letter-spacing:-0.8px;color:#141a3a;">Ce qu’il faut retenir<br><span class="dm-muted" style="color:#8a90b0;">avant de défiler.</span></h2>'
      + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">'
      + (ed.essentiels || []).slice(0, 3).map((t, i, all) => essentiel(t, i, i === all.length - 1)).join('')
      + '</table></td></tr>'
      + '<tr><td class="px" style="padding:22px 32px 14px 32px;">'
      + '<p class="dm-muted" style="margin:0 0 6px 0;' + F + 'font-size:11px;line-height:16px;font-weight:bold;letter-spacing:1.4px;text-transform:uppercase;color:#4a5172;">' + nb + ' retenue' + (nb > 1 ? 's' : '') + ' sur ' + lus + '</p>'
      + '<h2 class="dm-ink" style="margin:0;' + F + 'font-size:28px;line-height:32px;mso-line-height-rule:exactly;font-weight:bold;letter-spacing:-0.8px;color:#141a3a;">Les nouveautés du jour</h2>'
      + '</td></tr>'
      + articles.map(article).join('');

  const tuile = (valeur, libelle, pad) => '<td class="stack" width="33%" valign="top" style="' + pad + '"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td class="dm-pale" style="background:#f5f8ff;border-radius:14px;padding:14px 14px;">'
    + '<p class="dm-ink" style="margin:0;' + F + 'font-size:24px;line-height:28px;font-weight:bold;letter-spacing:-0.6px;color:#141a3a;">' + valeur + '</p>'
    + '<p class="dm-muted" style="margin:2px 0 0 0;' + F + 'font-size:13px;line-height:17px;color:#4a5172;">' + libelle + '</p></td></tr></table></td>';

  return '<!doctype html><html lang="fr" xmlns="http://www.w3.org/1999/xhtml"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="supported-color-schemes" content="light dark"><title>' + esc(sujetDe(ed)) + '</title>'
    + '<!--[if mso]><style>table,td,h2,h3,p,a{font-family:Arial,sans-serif !important;}</style><![endif]-->'
    + '<style>body{margin:0;padding:0;width:100%;-webkit-text-size-adjust:100%;}img{border:0;outline:none;text-decoration:none;display:block;}'
    + '@media (max-width:620px){.w100{width:100% !important;}.px{padding-left:20px !important;padding-right:20px !important;}.stack{display:block !important;width:100% !important;padding:0 0 12px 0 !important;}.h1{font-size:26px !important;line-height:30px !important;}}'
    + '@media (prefers-color-scheme: dark){.dm-bg{background:#0b0f2a !important;}.dm-card{background:#151a3d !important;border-color:#2a3163 !important;}.dm-pale{background:#1d2352 !important;}.dm-ink{color:#eef1ff !important;}.dm-soft{color:#cdd3f0 !important;}.dm-muted{color:#a3abd3 !important;}.dm-accent{color:#8fa0ff !important;}.dm-line{border-color:#2a3163 !important;}.dm-btn{background:#eef1ff !important;}.dm-btn a{color:#141a3a !important;}}'
    + '[data-ogsc] .dm-bg{background:#0b0f2a !important;}[data-ogsc] .dm-card{background:#151a3d !important;}[data-ogsc] .dm-ink{color:#eef1ff !important;}[data-ogsc] .dm-soft{color:#cdd3f0 !important;}[data-ogsc] .dm-muted{color:#a3abd3 !important;}</style></head>'
    + '<body class="dm-bg" style="margin:0;padding:0;background:#eef3ff;">'
    + '<div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:#eef3ff;opacity:0;">' + esc(preheader) + '&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;</div>'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" class="dm-bg" style="background:#eef3ff;"><tr><td align="center" style="padding:24px 12px 40px 12px;">'
    + '<!--[if mso]><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0"><tr><td><![endif]-->'
    + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" class="w100 dm-card" style="width:600px;max-width:600px;background:#ffffff;border-radius:22px;border-collapse:separate;overflow:hidden;">'
    + '<tr><td class="px" style="padding:22px 32px 18px 32px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>'
    + '<td width="44" valign="middle" style="width:44px;"><img src="' + IMG + '/tri-' + humeur + '-2x.png" width="40" height="40" alt="' + humeurAlt + '" style="display:block;width:40px;height:40px;' + F + 'font-size:11px;color:#4a5172;"></td>'
    + '<td valign="middle" class="dm-ink" style="' + F + 'font-size:21px;line-height:24px;mso-line-height-rule:exactly;font-weight:bold;letter-spacing:-0.4px;color:#141a3a;padding-left:6px;">Prisme.</td>'
    + '<td align="right" valign="middle" class="dm-muted" style="' + F + 'font-size:12.5px;line-height:17px;mso-line-height-rule:exactly;color:#4a5172;">' + esc(dateLongue) + '<br>' + numero + '</td>'
    + '</tr></table></td></tr>'
    + '<tr><td style="padding:0 16px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#e6efff" class="dm-pale" style="background:#e6efff;border-radius:16px;overflow:hidden;">'
    + (nb === 0
      ? '<img src="' + IMG + '/mail-rien-2x.png" width="568" height="170" alt="Tri dort : rien de marquant aujourd’hui." style="display:block;width:100%;max-width:568px;height:auto;border-radius:16px;' + F + 'font-size:13px;line-height:18px;color:#4a5172;text-align:center;">'
      : '<img src="' + IMG + '/mail-faisceau-2x.png" width="568" height="170" alt="Tri reçoit un rayon blanc (14 sources) et le décompose en 5 rayons de couleur (5 nouveautés)." style="display:block;width:100%;max-width:568px;height:auto;border-radius:16px;' + F + 'font-size:13px;line-height:18px;color:#4a5172;text-align:center;">')
    + '</td></tr></table></td></tr>'
    + '<tr><td class="px" style="padding:24px 32px 0 32px;"><h1 class="dm-ink h1" style="margin:0;' + F + 'font-size:32px;line-height:36px;mso-line-height-rule:exactly;font-weight:bold;letter-spacing:-1px;color:#141a3a;">' + nbsp(titre) + '</h1></td></tr>'
    + corps
    + '<tr><td class="px" style="padding:20px 32px 8px 32px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td bgcolor="#3c4fe0" style="background:#3c4fe0;border-radius:18px;padding:22px 22px 22px 18px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>'
    + '<td width="84" valign="middle" style="width:84px;"><img src="' + IMG + '/tri-content-2x.png" width="76" height="76" alt="Tri, content si ce numéro t’a servi" style="display:block;width:76px;height:76px;' + F + 'font-size:11px;color:#ffffff;"></td>'
    + '<td valign="middle" style="padding-left:8px;"><p style="margin:0 0 12px 0;' + F + 'font-size:19px;line-height:24px;mso-line-height-rule:exactly;font-weight:bold;color:#ffffff;">Ce numéro t’a été utile&nbsp;?</p>'
    + '<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>'
    + '<td bgcolor="#141a3a" style="background:#141a3a;border:1.5px solid #ffffff;border-radius:10px;"><a href="' + lienVote('utile') + '"' + cible + ' style="display:block;padding:9px 18px;' + F + 'font-size:14px;line-height:18px;font-weight:bold;color:#ffffff;text-decoration:none;">Utile</a></td>'
    + '<td width="10" style="width:10px;font-size:0;">&nbsp;</td>'
    + '<td style="border:1.5px solid #ffffff;border-radius:10px;"><a href="' + lienVote('pas-utile') + '"' + cible + ' style="display:block;padding:9px 16px;' + F + 'font-size:14px;line-height:18px;font-weight:bold;color:#ffffff;text-decoration:none;">Pas utile</a></td>'
    + '</tr></table></td></tr></table></td></tr></table></td></tr>'
    + '<tr><td class="px" style="padding:22px 32px 26px 32px;"><p class="dm-muted" style="margin:0 0 12px 0;' + F + 'font-size:11px;line-height:16px;font-weight:bold;letter-spacing:1.4px;text-transform:uppercase;color:#4a5172;">Le bilan de Tri</p>'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>'
    + tuile('14', 'sources lues', 'padding-right:8px;') + tuile(String(lus), 'articles parcourus', 'padding:0 4px;') + tuile(String(b.retenus != null ? b.retenus : nb), 'retenus', 'padding-left:8px;')
    + '</tr></table></td></tr>'
    + '<tr><td bgcolor="#141a3a" style="background:#141a3a;padding:28px 32px 30px 32px;" class="px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">'
    + '<tr><td style="' + F + 'font-size:17px;line-height:23px;font-weight:bold;color:#ffffff;">Une question, une source à proposer&nbsp;?</td></tr>'
    + '<tr><td style="padding:4px 0 18px 0;' + F + 'font-size:14px;line-height:21px;color:#c9cff0;">Réponds simplement à ce mail, il arrive chez Jean-Baptiste.</td></tr>'
    + '<tr><td style="border-top:1px solid #2f3768;padding-top:16px;' + F + 'font-size:12.5px;line-height:20px;color:#c9cff0;">'
    + 'Tu reçois Prisme parce que tu t’es inscrit sur <a href="https://prisme.krady.fr" target="_blank" style="color:#ffffff;text-decoration:underline;">prisme.krady.fr</a>.<br>'
    + (mode === 'mail' ? '<a href="' + lienDesinscription + '" target="_blank" style="color:#ffffff;text-decoration:underline;">Se désinscrire</a> &nbsp;·&nbsp; ' : '')
    + (mode === 'web' ? '' : '<a href="' + lienNavigateur + '"' + cible + ' style="color:#ffffff;text-decoration:underline;">Voir dans le navigateur</a> &nbsp;·&nbsp; ')
    + '<a href="https://github.com/jbkrady/prisme" target="_blank" style="color:#ffffff;text-decoration:underline;">Le projet</a>'
    + '</td></tr></table></td></tr>'
    + '</table><!--[if mso]></td></tr></table><![endif]--></td></tr></table></body></html>';
}

const sujet = sujetDe(ed);
const htmlWeb = rendre(ed, { jeton: 'web' }, 'web');
return destinataires.map((d) => ({ json: { email: d.email, sujet, html: rendre(ed, d, 'mail'), html_web: htmlWeb, id_edition: row.id, urls: (ed.articles || []).map((a) => a.url), date_edition: ed.date } }));
